import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.AddVolumeEntity{EntityRuntimeID: 7,
# EntityMetadata: map[string]any{"minecraft:fog": "spooky"},
# EncodingIdentifier: "endstone:volume", InstanceIdentifier: "instance",
# Bounds: [2]protocol.BlockPos{{1, 2, 3}, {4, 5, 6}}, Dimension: -1,
# EngineVersion: "1.21.0"}
FOG = bytes.fromhex(
    "070a00080d6d696e6563726166743a666f670673706f6f6b79000f656e6473746f6e653a766f6c756d6508"
    "696e7374616e6365020406080a0c0106312e32312e30"
)

# generated by gophertunnel b8bd735:
# &packet.AddVolumeEntity{}
DEFAULT = bytes.fromhex("000a000000000000000000000000")

# generated by gophertunnel b8bd735:
# &packet.AddVolumeEntity{EntityRuntimeID: 300,
# Bounds: [2]protocol.BlockPos{{-1, -1, -1}, {}}, Dimension: -1}
WIDE = bytes.fromhex("ac020a000000000101010000000100")

GOLDENS = [
    pytest.param(
        v2225.AddVolumeEntityPacket(
            entity_net_id=7,
            components=v2225.nbt.CompoundTag({"minecraft:fog": v2225.nbt.StringTag("spooky")}),
            json_identifier="endstone:volume",
            instance_name="instance",
            min_bounds=v2225.BlockPos(x=1, y=2, z=3),
            max_bounds=v2225.BlockPos(x=4, y=5, z=6),
            dimension_type=-1,
            min_engine_version="1.21.0",
        ),
        FOG,
        id="fog",
    ),
    pytest.param(v2225.AddVolumeEntityPacket(), DEFAULT, id="default"),
    pytest.param(
        v2225.AddVolumeEntityPacket(
            entity_net_id=300,
            min_bounds=v2225.BlockPos(x=-1, y=-1, z=-1),
            dimension_type=-1,
        ),
        WIDE,
        id="wide",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_add_volume_entity_is_packet_166(version):
    assert version.PACKETS[166] is version.AddVolumeEntityPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_volume_entity_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_volume_entity_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
